def is_valid(seq, pos, num):
    if seq[pos] != 0:
        return False
    apart = num + 1
    if pos + apart >= len(seq) or seq[pos + apart] != 0:
        return False
    return True

def solve_langford(n=7):
    length = 2 * n
    seq = [0] * length
    used = [False] * (n + 1)

    def backtrack(pos):
        if pos == length:
            return True
        if seq[pos] != 0:
            return backtrack(pos + 1)

        for num in range(n, 0, -1):  # start with larger numbers
            if not used[num]:
                apart = num + 1
                if pos + apart < length and seq[pos] == 0 and seq[pos + apart] == 0:
                    seq[pos] = num
                    seq[pos + apart] = num
                    used[num] = True
                    if backtrack(pos + 1):
                        return True
                    seq[pos] = 0
                    seq[pos + apart] = 0
                    used[num] = False
        return False

    if backtrack(0):
        return seq
    return None

result = solve_langford()
